150:  /// never accumulate; [cleanupOverlay] deletes it on shutdown and
497:  Future<void> cleanupOverlay() async {

  // env credential, seed the hub kill-switch key from the persisted
  // `~/.dap/config.json` `clientSecret` (the explicit prior opt-in from
  // `/dap start`). Without this the hub plugin never connects on a fresh
  // boot and `agent_directory` shows file inboxes only — hub peers (the
  // browser extension, embedded hosts) stay invisible from the CLI.
  seedHubBootCredential(
    dapEnvironment,
    masterSecretKey: envMasterSecret,
    clientSecretKey: envClientSecret,
    dapConfig: readDapConfig(defaultDapConfigFile(null, dapEnvironment)),
  );
  final hubPlugin = HubPlugin(environment: dapEnvironment);
  // gh-1888 review (AC8/AC14): the DAP env contract carries secrets
  // (plaintext channel privs in DAP_CHANNELS_JSON, the hub credential,
  // the key passphrase) and every bash child inherits them — register
  // them with BOTH masking systems BEFORE any tool runs, exactly like
  // the API keys above. The hub plugin additionally hooks every
  // runtime-resolved secret (decrypted privs, auto-provisioned
  // passphrases) into the same registration.
  registerDapEnvSecrets(
    dapEnvironment,
    redactor: redactor,
    redactionPipeline: redactionPipeline,
  );
  final resolved = await _resolvePlugins(
    effective,
    cliEnv,
    hubPlugin,
    dapEnvironment,
    // `fabric.hub: false` (issue #304 E6) — the legacy kill switch: no
    // hub primary in the messaging fabric, byte-identical directory.
    fabricHubAllowed: saved.fabric?.hub ?? true,
    secretRedactor: redactor,
    redactionPipeline: redactionPipeline,
  );

  if (!const {'code', 'architect', 'review'}.contains(effective.mode)) {
    _fail('unknown mode: ${effective.mode}');
  }
  final promptTemplateDirs = <String>[
    '$cwd/.fah/prompts',
    '$home/.fah/prompts',
    ...effective.promptTemplateDirs,
  ];

  final terminalIo = _TerminalCliIO(headless: headlessPrompt != null);
  // wire-serve (issue #1103): the io is a SILENT sink — every rendered
  // line dies there, so nothing TUI-shaped can ever reach the protocol
  // stream (the one stdout line is the startup line, written by the
  // transport, outside the CLI). Diagnostics keep stderr via writeln.
  CliIO io = wireServe.wireServe ? _WireServeSilentCliIO() : terminalIo;
====
    // The invite hub, not the zero-config local default — dial it directly
    // (process env only, ~/.dap/config.json untouched), with the enrolled
    // name-bound credential when one is stored.
    _environment['DAP_HUB_URL'] = preferred.hubUrl;
    _applyScopedIdentity(preferred.hubClientSecret, preferred.agentName);
    _connectedHubUrl = preferred.hubUrl;
  }

  void _applyScopedIdentity(String? secret, String? name) {
    _setEnvironmentValue('DAP_CLIENT_SECRET', secret);
    _setEnvironmentValue('DAP_AGENT_NAME', name);
    // A join-bundle / boot credential just entered the process env —
    // mask it like the startup-registered DAP env values (AC8/AC14).
    if (secret != null && secret.isNotEmpty) {
      registerDapSecret(
        secret,
        redactor: secretRedactor,
        pipeline: redactionPipeline,
      );
    }
  }

  void _setEnvironmentValue(String key, String? value) {
    if (value == null || value.isEmpty) return;
    _environment[key] = value;
  }

  Future<void> _tryScopedBootConnect(String hubUrl) async {
    try {
      await _ensureChannelConnection(hubUrl);
    } on Object catch (error) {
      _pluginIo?.writeln('[hub] scoped boot connect failed: $error');
    }
  }

  void _printBootConnectError(PluginContext context, Object error) {
    if (_hub.isDefaultUrl) {
      context.io.writeln('[hub] not configured — set DAP_HUB_URL to enable');
      return;
    }
    context.io.writeln('[hub] connect failed: $error');
  }

  /// Builds the scoped membership service (issue #1825) and points the
  /// vendored client at the RUNTIME overlay channel-key file, so the
  /// client's own key writes never leak scoped keys into the legacy
  /// global `~/.dap/channels.json`.
  void _initScopedMemberships(PluginContext context) {
    final home = _home ?? hub.defaultHome(_environment);
    // STABLE overlay name (not per-pid): one file per $HOME, rewritten
    // atomically on every (re)seed — the old `channels-$pid.json` shape
    // accumulated one plaintext-key file per run forever. Legacy pid
    // files of dead processes are swept here; the overlay is deleted on
    // clean shutdown where the host has a teardown path (and rewritten
    // 0600 on the next boot otherwise) — see docs/dap.md §15.3.
    final runtimeDir = '$home/.dap/runtime';
    unawaited(DapScopedMemberships.sweepLegacyOverlays(runtimeDir));
    final overlay = '$runtimeDir/channels.json';
    // AC8/AC14: the DAP env values are secrets inherited by every child
    // process — register them BEFORE anything can echo the environment,
    // and hook every runtime-resolved secret into the same masking.
    registerDapEnvSecrets(
      _environment,
