        newln = int(m.group(1)) - 1; continue
    if l.startswith('+') and not l.startswith('+++'):
        newln += 1; filemap[(cur,newln)] = '+'
    elif l.startswith('-') and not l.startswith('---'):
        continue
    elif l.startswith('\\'):
        continue
    else:
        newln += 1; filemap.setdefault((cur,newln), ' ')

